function update(error) {
  if (quickMatch && matchmakingURL)
    quickMatch.sync().catch((error) => status(error.message, true));
  if (session && session.replay) session.replay.update();
  if (error) status(error.message || String(error), true);
  $('quick-match').disabled =
    busy ||
    updates?.state === 'outdated' ||
    !matchmakingURL ||
    !!(quickMatch && quickMatch.active);
  $('cancel-search').hidden = !quickMatch || !quickMatch.active || !room.closed;
  if (!room || room.closed) {
    $('connect-panel').hidden = false;
    $('room-panel').hidden = true;
    $('host-panel').hidden = true;
    $('local-panel').hidden = true;
    $('game-panel').hidden = true;
    $('create').disabled = busy || updates?.state === 'outdated';
    $('join').disabled = busy || updates?.state === 'outdated';
    if (classicUI) classicUI.update();
    return;
  }
  $('start').disabled =
    busy ||
    updates?.state === 'outdated' ||
    !!room.handoff ||
    !lobbyReady(room.data) ||
    !room.ready() ||
    Object.values(room.data.members).some((member) => !member.connected) ||
    Object.keys(room.data.members).some(
      (id) => id !== room.selfId && !room.connected(id)
    );
  $('leave').disabled = busy || !!room.handoff;
  $('connect-panel').hidden = true;
  $('room-panel').hidden = false;
  $('host-panel').hidden = !room.isHost;
  $('local-panel').hidden = false;
  $('game-panel').hidden = !session.epoch;
  $('room-code').textContent = formatRoomCode(room.id);
  const invite = new URL(location.href);
  invite.search = '';
  invite.searchParams.set('room', room.id);
  $('invite-link').value = invite.toString();
  const data = room.data;
  $('room-visibility').value = data.visibility || 'private';
  $('room-visibility').disabled = busy || !room.isHost;
  $('arrangement').textContent =
    data.layout === 'four'
      ? text(
          'One human per browser · up to four browsers',
          '브라우저당 1명 · 최대 4개 브라우저'
        )
      : text(
          'Two humans per browser · two browsers',
          '브라우저당 2명 · 2개 브라우저'
        );
  const roster = $('roster');
  roster.replaceChildren();
  const pairs = data.layout === 'pairs';
  roster.classList.toggle('paired-roster', pairs);
  const slotControl = (slots) => {
    const container = document.createElement('div');
    container.className = 'slot-choice';
    container.dataset.choice = slots.join(',');
    return container;
  };
  const teams = pairs
    ? [
        [0, 1],
        [2, 3],
      ].map((slots) => {
        const team = document.createElement('li');
        team.className = 'roster-team';
        const players = document.createElement('ul');
        players.className = 'roster-team-players';
        team.append(players, slotControl(slots));
        roster.append(team);
        return players;
      })
    : null;
  for (let slot = 0; slot < 4; slot++) {
    const owner = data.seats[slot];
    const member = owner && data.members[owner];
    const card = document.createElement('li');
    card.className = 'player player-' + slot;
    const title = document.createElement('strong');
    title.textContent =
      'P' +
      (slot + 1) +
      ' · ' +
      (slot < 2 ? text('Left', '왼쪽') : text('Right', '오른쪽'));
    const name = document.createElement('span');
    name.textContent = member
      ? playerName(member, slot) +
        (owner === room.selfId ? text(' (you)', ' (나)') : '')
      : text('Computer / open slot', '컴퓨터 / 빈 자리');
    const connection = document.createElement('small');
    connection.textContent = member
      ? owner === data.hostId
        ? text('Host', '방장')
        : member.connected
        ? text('Connected', '연결됨')
        : text('Connecting…', '연결 중…')
      : text('AI fills this position', 'AI가 이 자리를 담당합니다');
    const icon = document.createElement('img');
    icon.className = 'player-sprite-icon';
    icon.src = lobbyPlayerIcons[slot];
    icon.alt = '';
    icon.width = icon.height = 64;
    card.append(icon, title, name, connection);
    if (room.isHost && owner && owner !== room.selfId) {
      const remove = document.createElement('button');
      remove.type = 'button';
      remove.className = 'secondary';
      remove.disabled = busy || !!room.handoff;
      remove.textContent = text('Remove', '내보내기');
      remove.addEventListener('click', () =>
        run(async () => {
          session.peerClosed(owner);
        })
      );
      card.appendChild(remove);
    }
    if (pairs) teams[Math.floor(slot / 2)].append(card);
    else {
      card.append(slotControl([slot]));
      roster.append(card);
    }
  }
  const me = data.members[room.selfId];
  $('my-positions').textContent =
    text('You control: ', '조작 선수: ') +
    (me ? me.slots.map((slot) => 'P' + (slot + 1)).join(' + ') : '—');
  const phase = {
    idle: text('Lobby', '대기실'),
    playing: text('Playing', '경기 중'),
    paused: text('Paused by host', '방장이 일시정지함'),
    finished: text('Match finished', '경기 종료'),
  }[session.phase];
  $('phase').textContent = phase;
  $('pause').disabled = busy || !session.epoch || session.phase === 'finished';
  $('pause').textContent =
    session.phase === 'paused'
      ? text('Resume', '계속')
      : text('Pause', '일시정지');
  $('back-lobby').disabled = busy || !session.epoch;
  if (!room.isHost && data.settings)
    updateSettingsForm(session.epoch ? session.settings : data.settings);
  if (classicUI) classicUI.update();
}
async function returnToLobby() {
  if (!room.isHost || room.closed) return;
  await room.store.update(room.id, { status: 'lobby' });
  update();
}
function setVisibility(value) {
  return run(async () => {
    if (!room.isHost) return;
    await room.store.request('visibility', { value });
    await quickMatch.sync();
  });
}
async function run(action, connecting = false) {
  if (busy) return;
  busy = true;
  const progress = connecting === 'create' ? 'create-request' : 'lookup';
  if (connecting) feedback.connecting(progress, true);
  $('create').disabled = true;
  $('join').disabled = true;
  update();
  try {
    await action();
  } catch (error) {
    status(error.message || String(error), true);
    if (error.message === VERSION_MISMATCH) {
      versionMessage.textContent = translateMessage(VERSION_MISMATCH);
      reloadButton.hidden = false;
    }
  } finally {
    busy = false;
    update();
    if (connecting) feedback.connecting(progress, false);
  }
}
function makeRoom(store) {
  return new OnlineRoom(
    {
      beforeConnect: () => updates.ensureCurrent(),
      connecting: (active) => feedback.connecting('room', active),
      creating: (active) => feedback.connecting('create', active),
      beforeHostTransfer: () => quickMatch?.sync(),
      hostTransferred: () =>
        status(text('Host transferred.', '방장을 변경했습니다.')),
      networkReset: () => session.stop(),
      change: () => {
        if (session.epoch && room.data.status === 'lobby') session.stop();
        session.refreshRoster();
        update();
      },
      open: (id) => {
        session.peerOpened(id);
        status(
          text(
            'Connected. The host can start the match.',
            '연결되었습니다. 방장이 경기를 시작할 수 있습니다.'
          )
        );
        update();
      },
      extraChannel: (id, channel) => session.replay.channel(id, channel),
      message: (id, message) => {
        if (session.replay && session.replay.message(id, message)) return;
        if (!classicUI || !classicUI.chat.receive(id, message))
          session.message(id, message);
      },
      peerClosed: (id) => session.peerClosed(id),
      ended: () => {
        session.stop();
        status(
          text(
            'The room closed or you left the room.',
            '방이 닫혔거나 방에서 나왔습니다.'
          )
        );
        update();
      },
      error: (error) => {
        status(error.message || String(error), true);
        if (error.message === VERSION_MISMATCH) {
          versionMessage.textContent = translateMessage(VERSION_MISMATCH);
          reloadButton.hidden = false;
        }
      },
    },
    store
  );
}

async function boot() {
  setUpUpdates();
  const savedNames = loadPlayerNames();
  ['nickname', 'pair-name'].forEach((id, index) => {
    if (savedNames[index] !== null) $(id).value = savedNames[index];
    $(id).addEventListener('input', () => savePlayerName(index, $(id).value));
  });
  Renderer.registerPlugin('prepare', Prepare);
  Renderer.registerPlugin('batch', BatchRenderer);
  CanvasRenderer.registerPlugin('prepare', CanvasPrepare);
  CanvasRenderer.registerPlugin('sprite', CanvasSpriteRenderer);
  Loader.registerPlugin(SpritesheetLoader);
  settings.RESOLUTION = 2;
  settings.SCALE_MODE = SCALE_MODES.NEAREST;
  settings.ROUND_PIXELS = true;
  if (ko)
    for (const [name, file] of Object.entries({
      MARK: 'mark',
      POKEMON: 'pokemon',
      PIKACHU_VOLLEYBALL: 'pikachu_volleyball',
      FIGHT: 'fight',
      WITH_COMPUTER: 'with_computer',
      WITH_FRIEND: 'with_friend',
      GAME_START: 'game_start',
    }))
      ASSETS_PATH.TEXTURES[name] = 'messages/ko/' + file + '.png';
  const renderer = autoDetectRenderer({
    width: DOUBLES_CONFIG.courtWidth * 2,
    height: 304,
    antialias: false,
    backgroundColor: 0,
    forceCanvas: true,
  });
  renderer.view.id = 'game-canvas';
  $('canvas-container').appendChild(renderer.view);
  const stage = new Container(),
    ticker = new Ticker(),
    loader = new Loader();
  loader.add(ASSETS_PATH.SPRITE_SHEET);
  Object.values(ASSETS_PATH.SOUNDS).forEach((url) => loader.add(url));
  await new Promise((resolve, reject) => {
    loader.onError.add((error) => reject(error));
    loader.load(resolve);
  });
  game = new PikachuVolleyball(stage, loader.resources, (width) => {
    renderer.resize(width, 304);
    document.documentElement.style.setProperty(
      '--aspect-ratio',
      String(width / 304)
    );
    document.documentElement.style.setProperty(
      '--inverse-aspect-ratio',
      String(304 / width)
    );
  });
  lobbyPlayerIcons = createPlayerIcons(
    loader.resources[ASSETS_PATH.SPRITE_SHEET].textures[
      ASSETS_PATH.TEXTURES.PIKACHU(0, 0)
    ],
    DOUBLES_CONFIG.playerTints
  );
  session = new OnlineMatch(game, ticker, update);
  let store = new SignalingStore();
  if (
    process.env.NODE_ENV === 'development' &&
    window.__PIKA_REQUIRE_TEST_STORE__ &&
    !window.__PIKA_TEST_STORE__
  )
    throw new Error('Local signaling fixture failed; Firebase access blocked.');
  // Browser tests may inject a local signaling store; production builds ignore this hook.
  if (
    process.env.NODE_ENV === 'development' &&
    ['localhost', '127.0.0.1'].includes(location.hostname) &&
    window.__PIKA_TEST_STORE__
  )
    store = window.__PIKA_TEST_STORE__;
  room = makeRoom(store);
  session.attachRoom(room);
  diagnostics = new NetworkDiagnostics(room, session);
  room.diagnostics = diagnostics;
  setUpDiagnosticsUI(room, session, diagnostics);
  diagnostics.start();
  session.replay = new RoomReplay(session, status);
  room.replay = session.replay;
  quickMatch = new QuickMatch({
    room,
    changed: () => update(),
    notify: (state, error) => {
      if (error)
        status(text('Quick Match: ', '빠른 대전: ') + error.message, true);
      else
        status(
          {
            waiting: text(
              'Finding a Quick Match room…',
              '빠른 대전 방을 찾는 중…'
            ),
            hosting: text(
              'Quick Match room open. Waiting for another player; empty positions may use computers.',
              '빠른 대전 방을 열었습니다. 다른 플레이어가 참가하면 빈 자리를 컴퓨터로 채워 시작할 수 있습니다.'
            ),
            joined: text(
              'Quick Match found. Connecting to the host…',
              '빠른 대전을 찾았습니다. 방장에게 연결 중…'
            ),
          }[state]
        );
    },
    request: async (body) => {
      if (!matchmakingURL)
        throw new Error(
          text(
            'Configure quick_match_config.js first.',
            '먼저 quick_match_config.js를 설정하세요.'
          )
        );
      const token = await store.token();
      const response = await fetch(
        matchmakingURL.replace(/\/$/, '') + '/v2/match',
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: 'Bearer ' + token,
          },
          body: JSON.stringify(body),
          signal: AbortSignal.timeout(10000),
        }
      );
      const data = await response.json();
      if (!response.ok)
        throw new Error(data.error || 'Quick Match request failed.');
      return data;
    },
  });
  ticker.maxFPS = matchSettings().fps;
  ticker.add(() => {
    session.tick();
    if (
      !busy &&
      room.isHost &&
      !room.closed &&
      room.data.visibility === 'public' &&
      session.phase === 'finished' &&
      session.epoch !== autoReturnedEpoch
    ) {
      autoReturnedEpoch = session.epoch;
      run(returnToLobby);
    }
    if (classicUI) classicUI.render();
    renderer.render(stage);
  });
  ticker.start();
  if (process.env.NODE_ENV === 'development')
    window.__volley = {
      game,
      session,
      room,
      updates,
      diagnostics,
      quickMatch,
      version: CLIENT_VERSION,
    };
  classicUI = setUpClassicUI({
    room,
    session,
    game,
    renderer,
    setVisibility,
    transferHost: (id) => run(() => room.transferHost(id)),
    applySettings: (value) =>
      run(async () => {
        if (!room.isHost) return;
        const checked = matchSettings(value);
        if (checked.topology !== room.data.settings.topology) {
          await room.rebuildNetwork(checked);
        } else if (session.epoch) {
          if (canUpdateLive(session.settings, checked))
            await session.updateLiveSettings(checked);
          else {
            await updates.ensureCurrent();
            await session.start(checked);
          }
        }
        updateSettingsForm(checked);
        status(text('Game options applied.', '경기 설정을 적용했습니다.'));
      }),
  });
  updateSettingsForm(matchSettings());
  renderPositions();
  update();
  status(
    text(
      'Ready. Create a room or find a friend’s room.',
      '준비되었습니다. 방을 만들거나 친구의 방을 찾으세요.'
    )
  );
  $('settings-form').addEventListener('submit', (event) =>
    event.preventDefault()
  );
  $('layout').addEventListener('change', () => {
    renderPositions();
  });
  $('quick-match').addEventListener('click', () =>
    run(async () => {
      await updates.ensureCurrent();
      await quickMatch.start({
        name: namesFromForm(),
        layout: $('layout').value,
        settings: settingsFromForm(),
      });
    })
  );
  $('cancel-search').addEventListener('click', () => {
    quickMatch.stop();
  });
  $('create').addEventListener('click', () =>
    run(async () => {
      await room.create(
        namesFromForm(),
        $('layout').value,
        slotsFromForm(),
        settingsFromForm()
      );
      status(
        text(
          'Room created. Choose a slot and share the invitation link.',
          '방을 만들었습니다. 자리를 고르고 초대 링크를 공유하세요.'
        )
      );
      update();
    }, 'create')
  );
  const join = () =>
    run(async () => {
      const id = normalizeRoomCode($('room-id').value);
      if (!/^[a-z0-9]{20}$/.test(id))
        throw new Error(
          text('Enter the 20-character room ID.', '20자리 방 ID를 입력하세요.')
        );
      await store.identity();
      const data = await store.peek(id);
      if (!data || data.schema !== ROOM_SCHEMA || data.status !== 'lobby')
        throw new Error(
          text(
            'Room not found, or the match has already started.',
            '방이 없거나 이미 경기가 시작되었습니다.'
          )
        );
      $('layout').value = data.layout;
      renderPositions();
      status(text('Connecting to the host…', '방장에게 연결 중…'));
      await room.join(id, namesFromForm(), slotsFromForm());
      update();
    }, true);
  $('join').addEventListener('click', join);
  $('room-id').addEventListener('keydown', (event) => {
    if (event.key === 'Enter' && !event.isComposing) {
      event.preventDefault();
      if (!$('join').disabled) $('join').click();
    }
  });
  $('leave').addEventListener('click', () =>
    run(async () => {
      if (quickMatch.active) await quickMatch.stop();
      session.stop();
      await room.leave();
      renderPositions();
      status(text('Left the room.', '방에서 나왔습니다.'));
    })
  );
  $('start').addEventListener('click', () =>
    run(async () => {
      await updates.ensureCurrent();
      if (!$('settings-form').reportValidity()) return;
      await session.start(settingsFromForm());
      if (quickMatch.active) await quickMatch.stop();
      status(text('Match started.', '경기를 시작했습니다.'));
      update();
    })
  );
  $('pause').addEventListener('click', () => {
    session.pause();
    update();
  });
  $('back-lobby').addEventListener('click', () => run(returnToLobby));
  $('room-visibility').addEventListener('change', () =>
    setVisibility($('room-visibility').value)
  );
  $('copy-link').addEventListener('click', async () => {
    const button = $('copy-link');
    if (button.getAttribute('aria-busy') === 'true') return;
    feedback.clearCopy(button);
    button.setAttribute('aria-busy', 'true');
    try {
      await navigator.clipboard.writeText($('invite-link').value);
      feedback.copied(button);
      status(text('Invitation link copied.', '초대 링크를 복사했습니다.'));
    } catch (error) {
      $('invite-link').select();
      status(
        text(
          'Copy the selected invitation link.',
          '선택된 초대 링크를 복사하세요.'
        )
      );
    } finally {
      button.removeAttribute('aria-busy');
    }
  });
  $('copy-code').addEventListener('click', async () => {
    if (!room.id) return;
    const button = $('copy-code');
    if (button.getAttribute('aria-busy') === 'true') return;
    feedback.clearCopy(button);
    button.setAttribute('aria-busy', 'true');
    try {
      await navigator.clipboard.writeText(formatRoomCode(room.id));
      feedback.copied(button);
      status(text('Room code copied.', '방 코드를 복사했습니다.'));
    } catch (error) {
      const range = document.createRange();
      range.selectNodeContents($('room-code'));
      const selection = window.getSelection();
      selection.removeAllRanges();
      selection.addRange(range);
      status(
        text('Copy the selected room code.', '선택된 방 코드를 복사하세요.')
      );
    } finally {
      button.removeAttribute('aria-busy');
    }
  });
  $('controls').addEventListener('change', () => {
    session.controls($('controls').value);
    update();
  });
  document.querySelectorAll('input,select').forEach((input) => {
    input.addEventListener('keydown', (event) => event.stopPropagation());
    input.addEventListener('keyup', (event) => event.stopPropagation());
  });
  window.addEventListener('beforeunload', () => {
    diagnostics.stop();
    if (quickMatch.active) quickMatch.stop();
    if (!room.closed) {
      session.stop();
      room.leave().catch(() => {});
    }
  });
  if (params.get('room')) {
    $('room-id').value = params.get('room');
  }
}
boot().catch((error) =>
  status(
    text('Could not load the game: ', '게임을 불러오지 못했습니다: ') +
      error.message,
    true
  )
);
